var arrangeCoins = function(n) {
    let left = 0, right = n, ans = 0;
    while (left <= right) {
        const mid = Math.floor((left + right) / 2);
        if ((mid * (mid + 1)) / 2 <= n) {
            ans = mid;
            left = mid + 1;
        } else {
            right = mid - 1;
        }
    }
    return ans;
};
